package com.citacloud.app.services; import com.citacloud.app.models.Servicio; import com.citacloud.app.repositories.ServicioRepository; import org.springframework.stereotype.Service; import java.math.BigDecimal; import java.util.*;
@Service public class ServicioService {private final ServicioRepository repo;public ServicioService(ServicioRepository r){repo=r;}public List<Servicio> listar(UUID empresa){return repo.findByEmpresaIdOrderByNombre(empresa);}public Servicio guardar(UUID empresa,UUID id,String codigo,String nombre,String descripcion,BigDecimal precio,boolean activo){if(nombre==null||nombre.isBlank()||precio==null||precio.signum()<0)throw new IllegalArgumentException("Nombre y precio válido son obligatorios.");Servicio s=id==null?new Servicio():repo.findByIdAndEmpresaId(id,empresa).orElseThrow(()->new IllegalArgumentException("Servicio no encontrado para esta empresa."));s.setEmpresaId(empresa);s.setCodigo(id==null?codigoAutomatico(empresa):(codigo==null||codigo.isBlank()?s.getCodigo():codigo.trim().toUpperCase()));s.setNombre(nombre.trim());s.setDescripcion(descripcion);s.setPrecio(precio);s.setActivo(activo);return repo.save(s);}private String codigoAutomatico(UUID empresa){int n=repo.findByEmpresaIdOrderByNombre(empresa).size()+1;String codigo;do{codigo="SER-%04d".formatted(n++);}while(repo.existsByEmpresaIdAndCodigoIgnoreCase(empresa,codigo));return codigo;}}
